// ── LaunchPad AI — Business Plan HTML Formatter ─────────────────────────────
// Parses the webhook payload and builds a professionally styled HTML document
// that the next node will convert to a PDF file.
// ─────────────────────────────────────────────────────────────────────────────

const body = $input.first().json.body;
const { userEmail, businessPlan } = body;

if (!userEmail || !businessPlan) {
  throw new Error('Invalid payload: both userEmail and businessPlan are required.');
}

const {
  companyName,
  executiveSummary,
  missionStatement,
  targetMarket,
  productsAndServices,
  revenueModel,
  marketingStrategy,
} = businessPlan;

const today = new Date().toLocaleDateString('en-US', {
  year: 'numeric',
  month: 'long',
  day: 'numeric',
});

const servicesList = productsAndServices
  .map(item => `<li>${item}</li>`)
  .join('\n');

const strategyList = marketingStrategy
  .map((step, i) => `<li><strong>Step ${i + 1}:</strong> ${step}</li>`)
  .join('\n');

const html = `<!DOCTYPE html>
<html lang='en'>
<head>
<meta charset='UTF-8'/>
<title>${companyName} — Business Plan</title>
<style>
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: Arial, sans-serif;
  color: #1a1a2e;
  padding: 48px 56px;
  line-height: 1.75;
  font-size: 13px;
}
.cover {
  text-align: center;
  padding: 32px 0 40px;
  border-bottom: 3px solid #e94560;
  margin-bottom: 36px;
}
.cover h1 { font-size: 30px; color: #16213e; }
.badge {
  display: inline-block;
  margin-top: 10px;
  padding: 4px 16px;
  background: #e94560;
  color: #fff;
  border-radius: 20px;
  font-size: 10px;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 1.2px;
}
.date { margin-top: 10px; color: #999; font-size: 11px; }
.section { margin-bottom: 28px; }
h2 {
  font-size: 11px;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 1.2px;
  color: #e94560;
  border-left: 4px solid #e94560;
  padding-left: 10px;
  margin-bottom: 10px;
}
p { color: #333; margin: 0; }
ul { padding-left: 20px; }
li { margin-bottom: 7px; color: #333; }
.footer {
  margin-top: 44px;
  padding-top: 14px;
  border-top: 1px solid #eee;
  text-align: center;
  color: #bbb;
  font-size: 10px;
}
</style>
</head>
<body>
<div class='cover'>
  <h1>${companyName}</h1>
  <div class='badge'>Business Plan</div>
  <div class='date'>Generated by LaunchPad AI &nbsp;|&nbsp; ${today}</div>
</div>
<div class='section'>
  <h2>Executive Summary</h2>
  <p>${executiveSummary}</p>
</div>
<div class='section'>
  <h2>Mission Statement</h2>
  <p>${missionStatement}</p>
</div>
<div class='section'>
  <h2>Target Market</h2>
  <p>${targetMarket}</p>
</div>
<div class='section'>
  <h2>Products &amp; Services</h2>
  <ul>${servicesList}</ul>
</div>
<div class='section'>
  <h2>Revenue Model</h2>
  <p>${revenueModel}</p>
</div>
<div class='section'>
  <h2>Marketing Strategy</h2>
  <ul>${strategyList}</ul>
</div>
<div class='footer'>
  Confidential &nbsp;|&nbsp; ${companyName} Business Plan &nbsp;|&nbsp; Powered by LaunchPad AI
</div>
</body>
</html>`;

return [{ json: { userEmail, companyName, html } }];
